import math
from html import escape
from pathlib import Path
from generate_speed_figures import (CAR, INK, MUTED, BLUE, TEAL, RED, AMBER,
                                   text, line, rect, path, car, curve, key, plot_frame)

HERE = Path(__file__).resolve().parent


def document(name, title, description, body, height=540, generator='generate_path_figures.py', eyebrow='STEERING AND TRAJECTORY'):
    markers = ''.join(f'<marker id="{key}" markerWidth="11" markerHeight="10" refX="9" refY="5" orient="auto" markerUnits="userSpaceOnUse"><path d="M1 1 L9 5 L1 9" fill="none" stroke="{color}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></marker>'
                      for key, color in [('blue', BLUE), ('teal', TEAL), ('red', RED)])
    svg = f'''<svg xmlns="http://www.w3.org/2000/svg" width="800" height="{height}" viewBox="0 0 800 {height}" role="img" aria-labelledby="title description">
<title id="title">{escape(title)}</title><desc id="description">{escape(description)}</desc>
<!-- Generated by {escape(generator)}. Copyright (C) 2026 Bernhard Wymann.
     GNU FDL 1.2 or later; no Invariant Sections or Cover Texts. -->
<defs>{markers}{CAR}</defs>
{rect(0,0,800,height,'#fffdfa',radius=16)}
<g font-family="Arial, Helvetica, sans-serif" fill="{INK}">
{text(24,29,eyebrow,11,BLUE,True)}
{text(24,62,title,26,bold=True)}{body}</g></svg>'''
    (HERE/name).write_bytes(svg.encode('utf-8'))


def road(d, width=52):
    return (path(d,'#bbc9cd',width+2)+path(d,'#f0f4f4',width)+
            path(d,'#a7b9c0',1.4,'stroke-dasharray="7 8"'))


def dot(x,y,label='',color=TEAL,dx=12,dy=-10):
    return f'<circle cx="{x:.3f}" cy="{y:.3f}" r="4" fill="{color}"/>'+ (text(x+dx,y+dy,label,15,color,True) if label else '')


def anticipation():
    body=''
    for offset,new in [(16,False),(408,True)]:
        b=rect(0,0,376,370,'#fff','#dfe6e7',12)
        b+=text(20,35,'Aim ahead' if new else 'React here',20,bold=True)
        b+=text(20,62,'Use a future centerline point.' if new else 'Use the road heading beside the car.',15,MUTED)
        b+=road('M60 260 H160 A100 100 0 0 0 260 160 V105')
        b+=car(106,260,90,.32)
        if new:
            tx,ty=160+100*math.sin(math.pi/3),260-100*(1-math.cos(math.pi/3))
            b+=line(133,250,tx-6,ty+3,TEAL,2.2,'marker-end="url(#teal)"')
            b+=dot(tx,ty,'Target',TEAL,13,28)
        else:
            b+=line(137,260,191,260,BLUE,2.2,'marker-end="url(#blue)"')
            b+=text(75,207,'Local tangent',15,BLUE)
        b+=text(20,324,'Same pose, same bend, same speed.',15,MUTED)
        b+=text(20,349,'Only the steering decision changes.',15,MUTED)
        body+=f'<g transform="translate({offset} 90)">{b}</g>'
    body+=text(24,503,'Arrows show steering references, not predicted vehicle trajectories.',15,MUTED)
    document('path-anticipation.svg','Give steering a point to aim at.',
             'Identical car poses on identical left bends compare the current local road tangent with the straight direction toward a future centerline target.',body)


def distances():
    cx,cy,r=260,185,185
    phi=math.pi/3;tx=cx+r*math.sin(phi);ty=cy+r*math.cos(phi)
    body=text(24,98,'One target. Two measurements with different jobs.',16,MUTED)
    body+=road(f'M90 {cy+r} H{cx} A{r} {r} 0 0 0 {cx+r} {cy} V140',64)
    body+=path(f'M185 {cy+r} H{cx} A{r} {r} 0 0 0 {tx} {ty}',BLUE,3)
    body+=car(185,390,90,.34)
    body+=line(185,390,tx,ty,TEAL,2.2,'stroke-dasharray="5 4"')
    body+=dot(185,cy+r,'S',BLUE,-10,-15)+dot(tx,ty,'Q',TEAL,13,4)
    body+=text(74,439,'Car position P',15,RED)
    body+=text(518,172,'Blue: lookahead L',18,BLUE,True)
    body+=text(518,199,'Follow the centerline from S.',15,MUTED)
    body+=text(518,263,'Teal: target vector Q − P',17,TEAL,True)
    body+=text(518,290,'Start at the actual car position.',15,MUTED)
    body+=text(518,316,'Its angle guides the steering.',15,MUTED)
    body+=text(24,495,'S is the centerline point at the car’s longitudinal position. P may be off-center.',15,MUTED)
    document('path-distance.svg','Along the road is not straight to the target.',
             'The car is offset from the centerline. Blue lookahead begins at the associated centerline point S and follows the road to Q. The dashed teal vector runs straight from the car position P to Q.',body)


def construction():
    body=''
    for offset,bend in [(16,False),(408,True)]:
        b=rect(0,0,376,365,'#fff','#dfe6e7',12)
        b+=text(20,35,'Curve: rotate' if bend else 'Straight: interpolate',20,bold=True)
        if bend:
            cx,cy,r=78,135,130;phi=math.pi/4
            tx,ty=cx+r*math.sin(phi),cy+r*math.cos(phi)
            b+=road('M78 265 A130 130 0 0 0 208 135',36)
            b+=line(cx,cy,78,265,BLUE,1.3)+line(cx,cy,tx,ty,TEAL,1.3)
            b+=path('M78 180 A45 45 0 0 0 109.82 166.82',AMBER,2)
            b+=dot(cx,cy,'C',MUTED,-20,-10)+dot(78,265,'S',BLUE,-22,8)+dot(tx,ty,'Q',TEAL,13,10)
            b+=text(104,194,'θ',18,AMBER)
            b+=text(235,159,'Left: +s/R',16,TEAL)
            b+=text(235,189,'Right: −s/R',16,TEAL)
            b+=text(20,316,'Rotate S about C by signed angle θ.',15,MUTED)
        else:
            b+=road('M55 225 H310',36)
            b+=dot(55,225,'S',BLUE,-5,36)+dot(310,225,'E',BLUE,-5,36)
            b+=dot(55+(310-55)*.4,225,'Q',TEAL,-5,-24)
            b+=line(55,155,157,155,TEAL,2,'marker-end="url(#teal)"')
            b+=text(72,139,'s = 0.4 ℓ',16,TEAL)
            b+=text(20,316,'Q = S + (s/ℓ)(E − S)',17,BLUE)
        b+=text(20,343,'Distances in metres; angles in radians.',15,MUTED)
        body+=f'<g transform="translate({offset} 95)">{b}</g>'
    body+=text(24,505,'Use centerline midpoints and centerline radius. The segment search uses metres.',15,MUTED)
    document('path-construction.svg','Build the point from track geometry.',
             'A straight target is an interpolated point between centerline endpoints. A left-curve target is a rotated starting point about the curve center; right curves use the opposite sign.',body)


def heading():
    px,py=155,380;yaw=math.radians(20);theta=math.radians(55)
    pos=lambda r,a:(px+r*math.cos(a),py-r*math.sin(a))
    target=pos(330,theta)
    body=text(24,98,'Example: car yaw ψ = 20°, target heading θ = 55°, error α = +35°',16,MUTED)
    body+=line(px,py,715,py,'#a7b9c0',1.5,'stroke-dasharray="5 5"')
    body+=text(650,405,'World +X',15,MUTED)
    body+=line(*pos(55,yaw),*pos(340,yaw),RED,2.2,'marker-end="url(#red)"')
    body+=line(*pos(55,theta),*target,TEAL,2.2,'marker-end="url(#teal)"')
    body+=car(px,py,70,.43)
    body+=dot(*target,'Target',TEAL,14,5)
    body+=curve([pos(160,a*theta/100) for a in range(101)],'#b1bec4',width=1.3)
    body+=curve([pos(115,yaw+(theta-yaw)*a/100) for a in range(101)],BLUE,width=2.5)
    body+=text(*pos(140,(theta+yaw)/2),'α',22,BLUE,True)
    body+=text(255,365,'ψ',18,RED)
    body+=text(455,242,'Car heading ψ',16,RED,True)
    body+=text(454,151,'Target heading θ',16,TEAL,True)
    body+=text(24,470,'Subtract yaw, wrap the difference, then scale by the steering lock.',16,MUTED)
    body+=text(24,501,'A positive wrapped error asks for left steering. This is a heading-error heuristic.',15,MUTED)
    document('path-heading.svg','Steer using an angular difference.',
             'A car yaw of 20 degrees and target direction of 55 degrees produce a positive heading error of 35 degrees. Reference arrows begin ahead of the car, with arcs showing angular differences.',body)


def lookahead():
    body,x,y=plot_frame(0,40,0,50,[0,10,20,30,40],[0,10,20,30,40,50],'Forward speed v (m/s)','Lookahead L (m)')
    for base,color,dash in [(4,MUTED,'5 5'),(8,TEAL,''),(17,BLUE,'8 4')]:
        body+=curve([(x(v),y(base+.33*v)) for v in range(41)],color,dash)
    body+=key(100,91,'L₀ = 4 m',MUTED,'5 5')+key(300,91,'L₀ = 8 m (default)',TEAL)+key(560,91,'L₀ = 17 m',BLUE,'8 4')
    body+=dot(x(20),y(14.6),'14.6 m',TEAL,12,-17)
    body+=text(24,511,'Calculated from L = L₀ + 0.33v. These are target distances, not measured car paths.',15,MUTED)
    document('path-lookahead.svg','A time term adds distance as speed rises.',
             'Calculated lookahead distances versus speed for base distances 4, 8 and 17 metres, all with time coefficient 0.33 seconds. The default at 20 metres per second is 14.6 metres.',body)


def radii():
    body=text(24,98,'Illustrative geometry: a candidate path can differ from the track centerline.',15,MUTED)
    body+=road('M85 395 H245 A210 210 0 0 0 455 185 V140',72)
    body+=path('M85 395 H245 A210 210 0 0 0 455 185 V140',BLUE,2,'stroke-dasharray="7 6"')
    body+=path('M85 395 H215 A240 240 0 0 0 455 155 V140',TEAL,2.8)
    body+=dot(245,185,'Track center',BLUE,-170,-5)
    body+=dot(215,155,'Path center',TEAL,-140,-15)
    body+=line(245,185,245+210*math.sin(math.pi/3),185+210*math.cos(math.pi/3),BLUE,1.2)
    body+=line(215,155,215+240*math.sin(math.pi/6),155+240*math.cos(math.pi/6),TEAL,1.2)
    body+=text(336,228,'R',20,BLUE,True)+text(258,286,'ρ',20,TEAL,True)
    angle=math.radians(35)
    body+=car(215+240*math.sin(angle),155+240*math.cos(angle),90-35,.25)
    body+=text(524,182,'Blue: track radius R',17,BLUE,True)
    body+=text(524,251,'Teal: path radius ρ',17,TEAL,True)
    body+=text(524,296,'Different centers.',15,MUTED)
    body+=text(524,323,'Different entry and exit.',15,MUTED)
    body+=text(24,475,'This candidate is constructed from circles; it is not a recorded simulator trajectory.',15,MUTED)
    body+=text(24,504,'Increasing R in a speed formula does not make the car follow the teal path.',15,MUTED)
    document('path-radius.svg','The car’s path has its own curvature.',
             'A blue quarter-circle track centerline and a teal candidate with larger radius and shifted center fit inside an illustrative road. The candidate begins turning earlier. It is geometric construction, not simulator data.',body)


def clearance():
    body=''
    for offset,angle in [(16,0),(408,20)]:
        b=rect(0,0,376,370,'#fff','#dfe6e7',12)
        b+=text(20,35,'Aligned' if angle==0 else 'Heading changed',20,bold=True)
        b+=rect(95,80,220,225,'#f0f4f4')
        b+=line(95,80,95,305,'#bbc9cd')+line(315,80,315,305,'#bbc9cd')
        b+=line(205,80,205,305,'#a7b9c0',1.4,'stroke-dasharray="7 8"')
        b+=line(60,150,60,105,BLUE,1.8,'marker-end="url(#blue)"')
        b+=text(31,181,'Travel',13,BLUE)
        b+=car(258,211,angle,.72)
        points=[]
        for x,y in [(-33,-64),(33,-64),(33,64),(-33,64)]:
            a=math.radians(angle)
            points.append((258+.72*(x*math.cos(a)-y*math.sin(a)),211+.72*(x*math.sin(a)+y*math.cos(a))))
        b+=curve(points+[points[0]],AMBER,'4 4',1.2)
        for x,y in points:b+=dot(x,y,color=AMBER)
        x,y=max(points)
        b+=line(x+5,y,315,y,AMBER,1.5)
        b+=text(20,333,'Same center position; compare the corners.',14,MUTED)
        b+=text(20,355,'Amber: schematic rectangular footprint.',14,MUTED)
        body+=f'<g transform="translate({offset} 90)">{b}</g>'
    body+=text(24,500,'Heading changes clearance too. These road edges are not barriers.',16,MUTED)
    document('path-clearance.svg','Check more than the center position.',
             'Two equal road panels show a car at the same center position with aligned and twenty-degree headings. Amber footprint corners reveal that rotating the car reduces its right-edge clearance.',body)


def projection():
    p=(170,350);q=(530,170);foot=(530,350)
    body=text(24,98,'Remove the component along the line to find the perpendicular distance.',16,MUTED)
    body+=line(65,350,725,350,BLUE,2,'marker-end="url(#blue)"')
    body+=line(*p,*q,TEAL,2.3,'marker-end="url(#teal)"')
    body+=line(*q,*foot,AMBER,2,'stroke-dasharray="5 5"')
    body+=path('M514 350 V334 H530',MUTED,1.3)
    body+=dot(*p,'P',BLUE,-10,29)+dot(*q,'Q',TEAL,12,-5)+dot(*foot,'Projection',BLUE,12,29)
    body+=text(265,226,'w = Q − P',18,TEAL)
    body+=text(552,254,'Perpendicular',16,AMBER,True)+text(552,277,'residual',16,AMBER,True)
    body+=text(288,391,'Component along the line',15,BLUE)
    body+=text(624,328,'Unit direction',15,BLUE)
    body+=text(24,472,'The residual is perpendicular: its dot product with the line direction is zero.',15,MUTED)
    body+=text(24,503,'This is an infinite line. For a finite segment, an endpoint may be nearer.',15,MUTED)
    document('path-projection.svg','Split a displacement into two parts.',
             'Displacement from line anchor P to point Q is split into its horizontal projection and perpendicular residual. A right-angle marker identifies the foot of the perpendicular on an infinite line.',body)


if __name__=='__main__':
    for generate in (anticipation,distances,construction,heading,lookahead,radii,clearance,projection):
        generate()
    print('Generated eight Chapter 4 geometry diagrams using the shared car.')
